SELECT
id,
name,
category_id,
price,
stock,
status,
description,
create_time,
update_time
FROM product




        AND name LIKE CONCAT('%', #{name}, '%')



        AND status = #{status}



        AND category_id = #{categoryId}



        AND price >= #{minPrice}



        AND price <= #{maxPrice}




